package main

import (
	"bufio"
	"fmt"
	"os"
)

type DateRec struct {
	DtId   string // PIC X(4) @0 len=4
	DtYyyy int64  // PIC 9(4) @4 len=4
	DtMm   int64  // PIC 9(2) @8 len=2
	DtDd   int64  // PIC 9(2) @10 len=2
}

var WsEofFlag string = "N"
var WsLeapFlag string = "N"
var WsQ int64 = 0
var WsR4 int64 = 0
var WsR100 int64 = 0
var WsR400 int64 = 0
var WsMaxDay int64 = 0
var WsValid int64 = 0
var WsBadMonth int64 = 0
var WsBadDay int64 = 0

var curRec DateRec
var dateLines []string
var dateIdx int
var dateOpen bool

func isInputDone() bool { return WsEofFlag == "Y" }
func isLeap() bool      { return WsLeapFlag == "Y" }

func parseNum(s string) int64 {
	var v int64 = 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c >= '0' && c <= '9' {
			v = v*10 + int64(c-'0')
		} else {
			v = v * 10
		}
	}
	return v
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	for len(s) < n {
		s += " "
	}
	return s
}

func format9(v int64, w int) string {
	mod := int64(1)
	for i := 0; i < w; i++ {
		mod *= 10
	}
	v = v % mod
	if v < 0 {
		v += mod
	}
	s := fmt.Sprintf("%d", v)
	for len(s) < w {
		s = "0" + s
	}
	if len(s) > w {
		s = s[len(s)-w:]
	}
	return s
}

func MainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		// If file does not exist, treat as empty (AT END immediately)
		dateLines = nil
		dateIdx = 0
		dateOpen = true
		ReadPara()
		for !isInputDone() {
			ProcessPara()
		}
		return
	}
	sc := bufio.NewScanner(f)
	// allow long lines
	sc.Buffer(make([]byte, 0, 64*1024), 10*1024*1024)
	var lines []string
	for sc.Scan() {
		lines = append(lines, sc.Text())
	}
	f.Close()
	dateLines = lines
	dateIdx = 0
	dateOpen = true
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
}

func ReadPara() {
	if dateIdx >= len(dateLines) {
		WsEofFlag = "Y"
		return
	}
	line := dateLines[dateIdx]
	dateIdx++
	// Remove trailing \r if present (in case of CRLF not handled)
	if len(line) > 0 && line[len(line)-1] == '\r' {
		line = line[:len(line)-1]
	}
	rec := padRight(line, 12)
	curRec.DtId = rec[0:4]
	curRec.DtYyyy = parseNum(rec[4:8])
	curRec.DtMm = parseNum(rec[8:10])
	curRec.DtDd = parseNum(rec[10:12])
}

func ProcessPara() {
	LeapPara()
	if curRec.DtMm < 1 || curRec.DtMm > 12 {
		WsBadMonth = (WsBadMonth + 1) % 100
		fmt.Fprint(os.Stdout, curRec.DtId+" BAD MONTH "+format9(curRec.DtMm, 2)+"\n")
	} else {
		DaysPara()
		if curRec.DtDd < 1 || curRec.DtDd > WsMaxDay {
			WsBadDay = (WsBadDay + 1) % 100
			fmt.Fprint(os.Stdout, curRec.DtId+" BAD DAY "+format9(curRec.DtDd, 2)+" MAX "+format9(WsMaxDay, 2)+"\n")
		} else {
			WsValid = (WsValid + 1) % 100
			fmt.Fprint(os.Stdout, curRec.DtId+" VALID "+format9(curRec.DtYyyy, 4)+"-"+format9(curRec.DtMm, 2)+"-"+format9(curRec.DtDd, 2)+"\n")
		}
	}
	ReadPara()
}

func LeapPara() {
	WsQ = (curRec.DtYyyy / 4) % 10000
	WsR4 = curRec.DtYyyy % 4
	WsQ = (curRec.DtYyyy / 100) % 10000
	// keep last divide's Q? COBOL does sequential divides overwriting WS-Q.
	// Above overwrote; final Q is from /400.
	WsR100 = curRec.DtYyyy % 100
	WsQ = (curRec.DtYyyy / 400) % 10000
	WsR400 = curRec.DtYyyy % 400
	// Recompute correctly in order (Q ends as /400, remainders preserved)
	// Remainders already set correctly.
	if WsR4 == 0 && (WsR100 != 0 || WsR400 == 0) {
		WsLeapFlag = "Y"
	} else {
		WsLeapFlag = "N"
	}
}

func DaysPara() {
	switch curRec.DtMm {
	case 2:
		if isLeap() {
			WsMaxDay = 29
		} else {
			WsMaxDay = 28
		}
	case 4, 6, 9, 11:
		WsMaxDay = 30
	default:
		WsMaxDay = 31
	}
}

func main() {
	MainPara()
	fmt.Fprint(os.Stdout, "VALID: "+format9(WsValid, 2)+" BAD MONTH: "+format9(WsBadMonth, 2)+" BAD DAY: "+format9(WsBadDay, 2)+"\n")
}
